<template><div class="grid"><div class="glass panel"><div class="panel-top"><h3>{{item.id?'Listening tahrirlash':'Yangi listening set'}}</h3><button v-if="item.id" class="link-btn" @click="reset">Bekor qilish</button></div><p class="help">Savollar: <code>savol | variant1 | variant2 | variant3 | to‘g‘ri javob</code>. Har qatorda bitta.</p><form @submit.prevent="$emit('save',{...item})"><div class="row"><label>Level<select v-model.number="item.level"><option v-for="n in 15" :key="n" :value="n">Level {{n}}</option></select></label><label>Sarlavha<input v-model.trim="item.title" required placeholder="At the airport" /></label></div><label>Audio uchun script<textarea v-model="item.script" rows="7" required placeholder="Good morning. I would like to..."/></label><label>Questions<textarea v-model="item.questionsRaw" rows="8" placeholder="Where is the speaker going? | Home | School | Airport | Airport"/></label><button class="primary" :disabled="saving">{{saving?'Saqlanmoqda…':item.id?'Saqlash':'Listening qo‘shish'}}</button></form></div><div class="glass panel"><div class="panel-top"><h3>Custom listening <span>{{items.length}}</span></h3></div><div v-if="!items.length" class="empty">Hali custom listening yo‘q.</div><div v-for="x in items" :key="x.id" class="item"><div><b>{{x.listening.title}}</b><span>Level {{x.listening.level}}</span><small>{{x.listening.items?.[0]?.questions?.length||0}} savol</small></div><div class="actions"><button @click="$emit('edit',x)"><i class="ti ti-pencil"></i></button><button class="danger" @click="$emit('delete',x.id)"><i class="ti ti-trash"></i></button></div></div></div></div></template>
<script setup>import {ref,watch} from 'vue';const props=defineProps({items:Array,initial:Object,saving:Boolean});const emit=defineEmits(['save','edit','delete']);const item=ref({...props.initial});watch(()=>props.initial,v=>item.value={...v},{deep:true});function reset(){item.value={level:1,title:'',script:'',questionsRaw:''}}</script><style scoped>@import './editor.css';</style>
